mapper.select:
SELECT os.id, om.order_no AS orderNo, os.sub_order_no AS subOrderNo, c.name AS customerName, om.create_user_id AS createUserId, om.order_type AS orderType, om.status, om.remark, os.status AS subOrderStatus, os.delivery_type AS deliveryType, os.delivery_remark AS deliveryRemark, DATE_FORMAT(os.expect_send_date, '%Y-%m-%d') AS expectSendDate, DATE_FORMAT(os.actual_send_date, '%Y-%m-%d') AS actualSendDate, os.picker_user_id AS pickerUserId, os.remark AS subRemark FROM order_sub os INNER JOIN order_master om ON os.master_id = om.id LEFT JOIN customer c ON om.customer_id = c.id WHERE os.is_delete = 0 AND om.is_draft = 0
AND os.sub_order_no LIKE CONCAT('%', #{query.subOrderNo}, '%')
AND om.customer_id = #{query.customerId}
AND om.create_user_id = #{query.createUserId}
AND os.status = #{query.subOrderStatus}
AND os.expect_send_date >= #{query.sendDateStart}
AND os.expect_send_date <= #{query.sendDateEnd}
ORDER BY os.expect_send_date ASC, os.sub_order_no ASC
